package com.ruoyi.warehouse.inbound;
import com.ruoyi.warehouse.catalog.WarehouseCatalog;
import com.ruoyi.warehouse.data.*;
import com.ruoyi.warehouse.security.WarehouseFields;
import com.ruoyi.warehouse.support.*;
import java.nio.charset.StandardCharsets;
import java.nio.file.*;
import java.util.*;
import java.util.concurrent.*;
import org.junit.jupiter.api.*;
import org.springframework.jdbc.datasource.DataSourceTransactionManager;
import static org.junit.jupiter.api.Assertions.*;
import static org.mockito.Mockito.*;

class MasterImportTest {
    InboundServiceTest f;MasterImportService service;WarehouseFields fields;WarehouseCatalog catalog=new WarehouseCatalog();
    @BeforeEach void setup()throws Exception{
        f=new InboundServiceTest();f.database();when(f.scope.admin()).thenReturn(true);when(f.scope.predicate(anyString(),anyList())).thenReturn("1=1");
        var existing=f.records.get("products","product",false);for(String key:List.of("id","_version","createdAt","updatedAt"))existing.remove(key);existing.put("expiryPolicy",catalog.fields("products").stream().filter(field->"expiryPolicy".equals(field.get("key"))).findFirst().orElseThrow().get("default"));f.jdbc.update("UPDATE wh_record SET business_json=? WHERE id='product'",WarehouseJson.write(existing));
        String ddl=Files.readString(Path.of("../sql/warehouse_031_master_import.sql")).replaceAll("(?m)^--.*$","").replaceAll(" CHARACTER SET [A-Za-z0-9_]+","").replaceAll(" COLLATE[= ]+[A-Za-z0-9_]+","").replaceAll(" ENGINE=InnoDB DEFAULT CHARSET=utf8mb4","").replace("LONGTEXT","VARCHAR(10000000)").replaceAll("JSON_VALID\\([^)]*\\)","TRUE").replaceAll(",\\s*KEY [^\\n]+","");for(String statement:ddl.split(";"))if(!statement.isBlank())f.jdbc.execute(statement);
        fields=mock(WarehouseFields.class);when(fields.transferFields(anyString(),anyBoolean())).thenAnswer(i->catalog.fields(i.getArgument(0)).stream().filter(field->!Boolean.TRUE.equals(field.get("readOnly"))).toList());when(fields.readable(anyString(),anyMap())).thenAnswer(i->WarehouseJson.copy(i.getArgument(1)));
        var master=new MasterDataService(catalog,f.records,f.scope,fields);service=new MasterImportService(f.records,master,catalog,f.scope,fields,new DataSourceTransactionManager(f.jdbc.getDataSource()));
    }
    Map<String,Object> preview(String data){return service.preview("products","create","products.csv",data.getBytes(StandardCharsets.UTF_8));}
    Map<String,Object> good(){return preview("client,sku,name,barcode\nclient,BULK-A,Bulk A,000123\nclient,BULK-B,Bulk B,000124\n");}
    Map<String,Object> body(Map<String,Object> row){return Map.of("requestId",UUID.randomUUID().toString(),"_version",row.get("_version"),"action","commit");}
    Map<String,Object> commit(Map<String,Object> row){return service.action("products",String.valueOf(row.get("id")),body(row));}
    long count(String sql){return f.jdbc.queryForObject(sql,Long.class);}
    @Test void previewRollsBackBusinessAuditAndHistoryThenOneBatchCommits(){f.jdbc.update("UPDATE wh_storage_control SET enabled=TRUE");long audits=count("SELECT COUNT(*) FROM wh_audit WHERE action_name='CREATE'");var row=good();assertEquals(true,row.get("valid"));assertEquals(1,count("SELECT COUNT(*) FROM wh_record WHERE kind='products'"));assertEquals(audits,count("SELECT COUNT(*) FROM wh_audit WHERE action_name='CREATE'"));assertEquals(0,count("SELECT COUNT(*) FROM wh_storage_batch"));var committed=commit(row);assertEquals("COMMITTED",committed.get("status"));assertEquals(3,count("SELECT COUNT(*) FROM wh_record WHERE kind='products'"));assertEquals(1,count("SELECT COUNT(*) FROM wh_storage_batch"));assertEquals(2,count("SELECT COUNT(*) FROM wh_storage_change"));}
    @Test void duplicateBarcodesWithinUploadHaveRowErrorsAndNoPartialRecords(){var result=preview("client,sku,name,barcode\nclient,A,A,SAME\nclient,B,B,SAME\n");assertEquals(false,result.get("valid"));assertEquals(3,WarehouseJson.maps(result.get("errors")).get(0).get("row"));assertEquals(1,count("SELECT COUNT(*) FROM wh_record WHERE kind='products'"));assertEquals(0,count("SELECT COUNT(*) FROM wh_master_import"));}
    @Test void duplicateNaturalKeyWithinUploadHasNoSideEffects(){var result=preview("client,sku,name\nclient,A,A\nclient,a,Other\n");assertEquals(false,result.get("valid"));assertEquals(1,count("SELECT COUNT(*) FROM wh_record WHERE kind='products'"));}
    @Test void referenceNameResolvesWithinScopeAndChangedReferenceInvalidatesWholeBatch(){var row=preview("client,sku,name\nSynthetic receiving,A,A\n");assertEquals(true,row.get("valid"));f.jdbc.update("UPDATE wh_record SET revision=revision+1 WHERE id='client'");assertThrows(WarehouseException.class,()->commit(row));assertEquals(1,count("SELECT COUNT(*) FROM wh_record WHERE kind='products'"));assertEquals("PREVIEW",service.get("products",String.valueOf(row.get("id"))).get("status"));}
    @Test void lateConflictRollsBackEarlierRowsAndAllowsSameRequestAfterResolution(){var row=good();var request=body(row);f.tx.execute(s->f.records.write("products","competing",Map.of("client","client","sku","BULK-B","name","Competing"),null,"bulk-b","client"));assertThrows(WarehouseException.class,()->service.action("products",String.valueOf(row.get("id")),request));assertEquals(0,count("SELECT COUNT(*) FROM wh_record WHERE natural_key='bulk-a'"));assertEquals(0,count("SELECT COUNT(*) FROM wh_operation_request WHERE operation_type='MASTER_IMPORT'"));f.tx.execute(s->{f.records.delete("products","competing",1);return null;});assertEquals("COMMITTED",service.action("products",String.valueOf(row.get("id")),request).get("status"));}
    @Test void updatesRequireVersionAndDoNotReplaceUnspecifiedFields(){var original=f.records.get("products","product",false);var missing=service.preview("products","update","update.csv","id,name\nproduct,Changed\n".getBytes(StandardCharsets.UTF_8));assertEquals(false,missing.get("valid"));var row=service.preview("products","update","update.csv","id,_version,name,barcode\nproduct,1,Changed,\n".getBytes(StandardCharsets.UTF_8));commit(row);var current=f.records.get("products","product",false);assertEquals("Changed",current.get("name"));assertEquals(original.get("sku"),current.get("sku"));assertEquals(2L,current.get("_version"));}
    @Test void auditFailureRollsBackEntireImportAndJournal(){var row=good();f.jdbc.execute("ALTER TABLE wh_audit ADD CONSTRAINT import_audit_failure CHECK(action_name<>'MASTER_IMPORT_COMMIT')");assertThrows(RuntimeException.class,()->commit(row));assertEquals(1,count("SELECT COUNT(*) FROM wh_record WHERE kind='products'"));assertEquals("PREVIEW",service.get("products",String.valueOf(row.get("id"))).get("status"));assertEquals(0,count("SELECT COUNT(*) FROM wh_operation_request WHERE operation_type='MASTER_IMPORT'"));}
    @Test void concurrentReplayCreatesOneBatch()throws Exception{var row=good();var request=body(row);var pool=Executors.newFixedThreadPool(2);try{var calls=List.<Callable<Map<String,Object>>>of(()->service.action("products",String.valueOf(row.get("id")),request),()->service.action("products",String.valueOf(row.get("id")),request));var result=pool.invokeAll(calls);assertEquals(WarehouseJson.write(result.get(0).get()),WarehouseJson.write(result.get(1).get()));}finally{pool.shutdownNow();}assertEquals(3,count("SELECT COUNT(*) FROM wh_record WHERE kind='products'"));assertEquals(1,count("SELECT COUNT(*) FROM wh_audit WHERE action_name='MASTER_IMPORT_COMMIT'"));}
    @Test void originalActorOwnsPreviewAndRevokedFieldWritePermissionBlocksReplay(){var row=good();var request=body(row);service.action("products",String.valueOf(row.get("id")),request);when(f.scope.actor()).thenReturn(99L);assertThrows(WarehouseException.class,()->service.get("products",String.valueOf(row.get("id"))));when(f.scope.actor()).thenReturn(7L);doThrow(WarehouseException.forbidden()).when(fields).writable(eq("products"),anyMap());assertThrows(WarehouseException.class,()->service.action("products",String.valueOf(row.get("id")),request));}
    @Test void unusedPreviewCanBeCancelledEvenIfItsReferenceHasGone(){var row=good();f.jdbc.update("DELETE FROM wh_record WHERE id='client'");var cancelled=service.action("products",String.valueOf(row.get("id")),Map.of("requestId",UUID.randomUUID().toString(),"_version",1,"action","cancel"));assertEquals("CANCELLED",cancelled.get("status"));assertThrows(WarehouseException.class,()->commit(row));}
    @Test void corruptedPreviewCannotBeReadOrApplied(){var row=good();f.jdbc.update("UPDATE wh_master_import SET document_hash=REPEAT('0',64)");assertThrows(WarehouseException.class,()->commit(row));assertEquals(1,count("SELECT COUNT(*) FROM wh_record WHERE kind='products'"));}
    @Test void sharedCatalogBatchesUseSameValidationAndAdminWriteBoundary(){
        for(String kind:List.of("suppliers","channels")){
            var duplicate=service.preview(kind,"create","records.csv","name\nShared\nshared\n".getBytes(StandardCharsets.UTF_8));assertEquals(false,duplicate.get("valid"));assertEquals(0,count("SELECT COUNT(*) FROM wh_record WHERE kind='"+kind+"'"));
            var preview=service.preview(kind,"create","records.csv","name,active\nShared,true\n".getBytes(StandardCharsets.UTF_8));assertEquals(true,preview.get("valid"));var applied=service.action(kind,String.valueOf(preview.get("id")),body(preview));assertEquals("COMMITTED",applied.get("status"));assertEquals(1,count("SELECT COUNT(*) FROM wh_record WHERE kind='"+kind+"'"));
        }
        doThrow(WarehouseException.forbidden()).when(f.scope).requireAdministrator();assertThrows(WarehouseException.class,()->service.preview("suppliers","create","records.csv","name\nDenied\n".getBytes(StandardCharsets.UTF_8)));
    }
    @Test void restrictedHeadersAreRejectedBeforeDataIsRead(){when(fields.transferFields("products",true)).thenReturn(catalog.fields("products").stream().filter(field->!Boolean.TRUE.equals(field.get("financial"))).toList());assertThrows(WarehouseException.class,()->preview("client,sku,name,firstPick\nclient,A,A,1.23\n"));}
}
